#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main() {
    int n;
    scanf("%d", &n);

    int a[1505];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    qsort(a, n, sizeof(int), cmp);

    long long ans = 0;

    for (int k = 2; k < n; k++) {
        int i = 0;
        int j = k - 1;

        while (i < j) {
            if (a[i] + a[j] > a[k]) {
                ans += (j - i);
                j--;
            } else {
                i++;
            }
        }
    }

    printf("%lld\n", ans);

    return 0;
}
